draw:
var g = 9.8;
var m1 = p.m1, m2 = p.m2;
var a = (m1 - m2) * g / (m1 + m2);
var T = 2 * m1 * m2 * g / (m1 + m2);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var cx = W * 0.5;
var cy = H * 0.16;
var R = Math.min(W, H) * 0.07;
var half = W * 0.20;
var rest = H * 0.55;
var span = H * 0.22;

// animate: let the heavier side fall, then loop
var cycle = 2.6;
var s = t % cycle;
var d = 0.5 * a * s * s;
var maxd = span;
if (d > maxd) { d = maxd; }
if (d < -maxd) { d = -maxd; }

var y1 = rest + d;
var y2 = rest - d;

// ceiling bracket
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(cx - W * 0.12, cy - R - 14);
ctx.lineTo(cx + W * 0.12, cy - R - 14);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(cx, cy - R - 14);
ctx.lineTo(cx, cy - R);
ctx.stroke();

// pulley
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.arc(cx, cy, R, 0, Math.PI * 2);
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.arc(cx, cy, 2.5, 0, Math.PI * 2);
ctx.fill();

// rope
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(cx - R, cy);
ctx.lineTo(cx - R, y1);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(cx + R, cy);
ctx.lineTo(cx + R, y2);
ctx.stroke();
ctx.beginPath();
ctx.arc(cx, cy, R, Math.PI, 0, true);
ctx.stroke();

// blocks, area scaled with mass
function block(x, y, m, name) {
  var w = 22 + m * 3.2;
  var h = 16 + m * 1.6;
  ctx.fillStyle = C.figure;
  ctx.globalAlpha = 0.25;
  ctx.fillRect(x - w / 2, y, w, h);
  ctx.globalAlpha = 1;
  ctx.strokeStyle = C.ink;
  ctx.strokeRect(x - w / 2, y, w, h);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText(name + " = " + m.toFixed(1) + " kg", x, y + h + 14);
}
block(cx - R, y1, m1, "m1");
block(cx + R, y2, m2, "m2");

// tension arrows on the ropes
ctx.strokeStyle = C.ink;
ctx.fillStyle = C.ink;
function up(x, y, len) {
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x, y - len);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x, y - len);
  ctx.lineTo(x - 4, y - len + 7);
  ctx.lineTo(x + 4, y - len + 7);
  ctx.closePath();
  ctx.fill();
}
up(cx - R, y1 - 4, 26);
up(cx + R, y2 - 4, 26);
ctx.textAlign = "right";
ctx.fillText("T", cx - R - 7, y1 - 20);
ctx.textAlign = "left";
ctx.fillText("T", cx + R + 7, y2 - 20);

// acceleration direction marker
ctx.fillStyle = C.accent;
ctx.textAlign = "center";
var dirTxt = a > 0.02 ? "m1 falls" : (a < -0.02 ? "m2 falls" : "balanced");
ctx.fillText(dirTxt, cx, H - 8);

out.note = "a = " + Math.abs(a).toFixed(2) + " m/s^2,  T = " + T.toFixed(1) +
  " N   (m1 g = " + (m1 * g).toFixed(1) + " N, m2 g = " + (m2 * g).toFixed(1) + " N)";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;
ctx.textAlign = "center";

var tableY = H * 0.42;
var edgeX = W * 0.62;
var bw = W * 0.16, bh = H * 0.15;
var bx = W * 0.26, by = tableY - bh;

// table
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(W * 0.05, tableY);
ctx.lineTo(edgeX, tableY);
ctx.lineTo(edgeX, H * 0.72);
ctx.stroke();

// block A on the table
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.25;
ctx.fillRect(bx, by, bw, bh);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.ink;
ctx.strokeRect(bx, by, bw, bh);
ctx.fillStyle = C.ink;
ctx.fillText("M on table", bx + bw / 2, by - 6);

var acx = bx + bw / 2, acy = by + bh / 2;

function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  var ang = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 8 * Math.cos(ang - 0.4), y2 - 8 * Math.sin(ang - 0.4));
  ctx.lineTo(x2 - 8 * Math.cos(ang + 0.4), y2 - 8 * Math.sin(ang + 0.4));
  ctx.closePath();
  ctx.fill();
}

var L = H * 0.20;
arrow(acx, acy, acx, acy - L, C.figure);
arrow(acx, acy, acx, acy + L, C.figure);
arrow(acx, acy, acx + bw * 0.95, acy, C.accent);
ctx.fillStyle = C.figure;
ctx.textAlign = "right";
ctx.fillText("N", acx - 6, acy - L + 4);
ctx.fillText("Mg", acx - 6, acy + L);
ctx.textAlign = "left";
ctx.fillStyle = C.accent;
ctx.fillText("T", acx + bw * 0.95 + 5, acy + 4);

// rope over the pulley
var R = Math.min(W, H) * 0.05;
var pcx = edgeX, pcy = tableY - R;
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(bx + bw, tableY - R * 2);
ctx.lineTo(pcx, tableY - R * 2);
ctx.stroke();
ctx.beginPath();
ctx.arc(pcx, pcy, R, -Math.PI / 2, 0);
ctx.stroke();

var hy = H * 0.60;
ctx.beginPath();
ctx.moveTo(pcx + R, pcy);
ctx.lineTo(pcx + R, hy);
ctx.stroke();

ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.arc(pcx, pcy, R, 0, Math.PI * 2);
ctx.stroke();

// hanging block
var hw = W * 0.13, hh = H * 0.14;
var hx = pcx + R - hw / 2;
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.25;
ctx.fillRect(hx, hy, hw, hh);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.ink;
ctx.strokeRect(hx, hy, hw, hh);

var hcx = hx + hw / 2, hcy = hy + hh / 2;
var L2 = H * 0.17;
arrow(hcx, hcy, hcx, hcy - L2, C.accent);
arrow(hcx, hcy, hcx, hcy + L2, C.figure);
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("T", hcx + 6, hcy - L2 + 6);
ctx.fillStyle = C.figure;
ctx.fillText("mg", hcx + 6, hcy + L2);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("m hanging", hcx, hy - 6);

// constraint note
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("same rope, so the same T at both ends", W * 0.05, H * 0.92);
ctx.fillText("same rope length, so the same |a|", W * 0.05, H * 0.98);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var g = 9.8;
var Wload = p.load * g;
var pull = p.pull;              // metres the free end is drawn down
var rise = pull / 2;            // load rises half as far

var scale = H * 0.22;           // pixels per metre of drawn travel
var ceil = H * 0.14;

var anchorX = W * 0.30;
var fixedX = W * 0.70;
var R = Math.min(W, H) * 0.055;

// ceiling
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(W * 0.10, ceil);
ctx.lineTo(W * 0.90, ceil);
ctx.stroke();
for (var i = 0; i < 9; i++) {
  var hx = W * 0.10 + i * W * 0.10;
  ctx.beginPath();
  ctx.moveTo(hx, ceil);
  ctx.lineTo(hx - 7, ceil - 8);
  ctx.stroke();
}

// movable pulley position
var mpY = H * 0.62 - rise * scale;

// fixed pulley
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.arc(fixedX, ceil + R, R, 0, Math.PI * 2);
ctx.stroke();

// movable pulley
ctx.beginPath();
ctx.arc(anchorX + R, mpY, R, 0, Math.PI * 2);
ctx.stroke();

// rope: anchor -> down left side -> round movable pulley -> up -> over fixed pulley -> down free end
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(anchorX, ceil);
ctx.lineTo(anchorX, mpY);
ctx.stroke();
ctx.beginPath();
ctx.arc(anchorX + R, mpY, R, Math.PI, 0, false);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(anchorX + 2 * R, mpY);
ctx.lineTo(anchorX + 2 * R, ceil + R);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(anchorX + 2 * R, ceil + R);
ctx.lineTo(fixedX, ceil + R);
ctx.stroke();
ctx.beginPath();
ctx.arc(fixedX, ceil + R, R, -Math.PI / 2, 0);
ctx.stroke();
var freeEndY = H * 0.50 + pull * scale;
if (freeEndY > H * 0.93) { freeEndY = H * 0.93; }
ctx.beginPath();
ctx.moveTo(fixedX + R, ceil + R);
ctx.lineTo(fixedX + R, freeEndY);
ctx.stroke();

// load hanging under movable pulley
var lw = W * 0.14, lh = H * 0.12;
var lx = anchorX + R - lw / 2, ly = mpY + R;
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(anchorX + R, mpY + R);
ctx.lineTo(anchorX + R, ly + 2);
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.25;
ctx.fillRect(lx, ly, lw, lh);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.ink;
ctx.strokeRect(lx, ly, lw, lh);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText(p.load.toFixed(0) + " kg", lx + lw / 2, ly + lh / 2 + 4);

// labels
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("tied", anchorX - 20, ceil - 14);
ctx.textAlign = "center";
ctx.fillText("T", anchorX - 8, (ceil + mpY) / 2);
ctx.fillText("T", anchorX + 2 * R + 9, (ceil + mpY) / 2);
ctx.fillStyle = C.accent;
ctx.fillText("pull, F = T", fixedX + R, freeEndY + 15);

// marker of travel
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath();
ctx.moveTo(W * 0.06, H * 0.62 + R);
ctx.lineTo(anchorX - R, H * 0.62 + R);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("start", W * 0.06, H * 0.62 + R - 5);

out.note = "free end pulled " + pull.toFixed(2) + " m, load rose " + rise.toFixed(2) +
  " m   |   weight " + Wload.toFixed(1) + " N held by 2T, so T = " + (Wload / 2).toFixed(1) + " N";
